def icon(name, label=''):
    a=('role="img" aria-label="'+escape(label,quote=True)+'"') if label else 'aria-hidden="true"'
    return '<svg class="mi" viewBox="0 0 24 24" focusable="false" '+a+'>'+MATERIAL.get(name,MATERIAL['search'])+'</svg>'


def source_icon(source, size=24):
    return '<img class="google-source-icon" src="'+LOGOS[source]+'" alt="" aria-hidden="true" width="'+str(size)+'" height="'+str(size)+'">'


